#include <iostream>
#include <print>

int main() {
    int a = 0;
    int b = 0;

    std::print("请输入两个整数（空格隔开）: ");
    std::cin >> a >> b;

    std::println("a = {}, b = {}", a, b);   // 敲 hello 之后两个都还是 0
    std::println("它们的和是 {}", a + b);

    return 0;
}

